/* From Uiverse.io by coding-masala - Tags: radio, advanced */
.__UIV_SCOPE__ * {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.__UIV_SCOPE__ {
  font-family: Arial, sans-serif;
  background-color: #f1f1f1;
  padding: 20px;
}

.__UIV_SCOPE__ .radio-group {
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ .radio-label {
  display: flex;
  align-items: center;
  padding: 0.5em;
  margin-bottom: 0.5em;
  background-color: #fff;
  border: 1px solid #ccc;
  border-radius: 4px;
  transition: background-color 0.2s, border-color 0.2s;
}

.__UIV_SCOPE__ .radio-label:hover {
  background-color: #e6e6e6;
}

.__UIV_SCOPE__ .radio-input {
  position: absolute;
  opacity: 0;
}

.__UIV_SCOPE__ .radio-input:checked + .radio-label {
  background-color: #ffc3c3;
  border-color: #ff1111;
}

.__UIV_SCOPE__ .radio-input:focus + .radio-label {
  outline: 2px solid #ff1111;
}

.__UIV_SCOPE__ .radio-inner-circle {
  display: inline-block;
  width: 1em;
  height: 1em;
  border: 2px solid #888;
  border-radius: 50%;
  margin-right: 0.5em;
  transition: border-color 0.2s;
  position: relative;
}

.__UIV_SCOPE__ .radio-label:hover .radio-inner-circle {
  border-color: #555;
}

.__UIV_SCOPE__ .radio-input:checked + .radio-label .radio-inner-circle {
  border-color: #ff1111;
}

.__UIV_SCOPE__ .radio-input:checked + .radio-label .radio-inner-circle::after {
  content: '';
  display: block;
  width: 0.5em;
  height: 0.5em;
  background-color: #ff1111;
  border-radius: 50%;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}
